#!/usr/bin/env bash
# Owner order 2026-11-15 ("option 1, approve list, report per arm"). Two Sonnet sessions, each wrapped in the shared slot lock:
#  A) recall-fixture repair: repository snapshots for the four recall plans and more C8 seeds, so the freeze gate can be re-run fairly.
#  B) /sc:workflow plan for the owner-approved format-forgiveness rule in the Sweep Sheet ledger parser, reported strict and lenient per arm.
# Neither session edits extractors, cards, briefs, words, formats or rank (the frozen files). Sonnet only; no Opus.
set -u -o pipefail
REPO=/home/coder/workspaces/worktrees/IronClaude/eval-tasklist-review-panel
SW=$REPO/.dev/eval-workspaces/tasklist-review-panel/20261114-sweep-sheet
LOCK=$REPO/.dev/eval-workspaces/tasklist-review-panel/20261114-collab-process/with-slot.sh
mkdir -p "$SW/option1-report"
BAN="STRICT READ BAN: do not open, grep or run anything that prints: $SW/sweep/*.py, $SW/analysis/g0.py, $SW/tests/test_e*.py, $SW/tests/test_recall.py, any ground-truth*.json or score*.json, anything under $SW/results/ (except where this prompt names a file), $SW/runs/, .dev/eval-workspaces/tasklist-review-panel/20261111-a1/ 20261113-collab/ 20261114-recipe-ledger/, .dev/reflect/, .dev/brainstorms/, and the three study packages TASK-WF-designSpec-20261107-075614, TASK-WF-makeTheAliasOnly-20261105-051649, TASK-WF-design-20261108-041415. Do not run the freeze tests or any extractor."

PA="You are a fresh Sonnet session repairing the recall fixtures of the Sweep Sheet freeze check. Work in $REPO. Read: $SW/results/freeze-check-20261115.md (the failing result and the two fixture gaps), $SW/fixtures/recall/AUTHORS.md, $SW/fixtures/recall/*/seeds.json and seeded.md (your own earlier seeds are the second author's: you may read them), $SW/TESTING.md section 2 (F-RECALL), $SW/bin/build-sandbox.sh (how a snapshot of a repository at a base commit is built; read it as a how-to; do not change it), and $SW/DESIGN.md DD-5 (the search scope: tracked files under tests/, scripts/, docs/, root files, and change-log style files, minus .dev/ and dependency folders). $BAN
TASK 1: for each of the 4 plans under $SW/fixtures/recall/, create snapshot/ = the repository as it was BEFORE that plan was implemented (the last commit before the plan package was created: use git log and the package's creation date, record the sha), limited to the DD-5 scope so it stays small, built with git archive into $SW/fixtures/recall/<plan>/snapshot/, with .dev/ removed. Write a script $SW/fixtures/recall/build-snapshots.sh that rebuilds them from the recorded shas, and record each base sha in AUTHORS.md. Do not commit the snapshot folders (they stay untracked; the script rebuilds them) and say so in AUTHORS.md.
TASK 2: add C8 seeds so that at least 5 C8 seeds exist across the four plans. A C8 seed is a plan task that edits or renames a file, string or behavior that an existing test or document in the snapshot pins, where the plan never names or runs that test or document; the quote in seeded.md is the plan sentence that makes the edit. Verify each C8 seed against the snapshot with git grep (show the pinned file in seeds.json as field note). Keep every quote exactly once in seeded.md. Do not change existing seeds. Update seeds.json, seeded.md and the seed counts in AUTHORS.md; keep the 'second author' statement true: say a fresh Sonnet session did this repair on 2026-11-15, that it had not read the extractors or any ground truth, and that it knew the first failing result.
Hard limits: write only under $SW/fixtures/recall/. Do not edit anything else. Do not stage, commit or push. Start no model or sub-agent other than claude-sonnet-5-5 or claude-haiku-5-5. Use uv for Python. When done write $SW/option1-report/RECALL-REPAIR.md: files created, base shas, seed counts per class, what you could not do."

PB="/sc:workflow \"Add owner-approved format forgiveness to the Sweep Sheet ledger parser, reported strict and lenient per arm. Context: $SW/DESIGN.md (ledger-v1 and the checker, sections 9 and 13), $SW/scaffold/ledgerv1.py, $SW/analysis/analyze.py (report), $SW/TESTING.md, $SW/results/owner-decisions.md. OWNER ORDER 2026-11-15: make format checks forgive small, harmless deviations when the content is correct, and record every forgiveness; approved list for the Sweep Sheet ledger parser only: verdict word in lower or mixed case; trailing comma or extra whitespace on a JSON line; capitalised code-fence language; item id wrapped in backticks or followed by a colon; ledger heading written as '### Ledger' or 'Ledger:'; a heading between the ledger block and the findings block (flagged loose_layout, not missing); quote matching across line wraps and doubled spaces (verify the existing matcher; add only what is missing). Never forgiven: a missing ledger, an unknown item, a verdict that is not OK, PROBLEM or UNSURE after case folding, a quote not found in the plan, rows over budget, a missing CB-3 sentence on a blocking finding. Every forgiven item is recorded (raw text kept, a forgiven list with the rule name). The analysis reports the compliance gate and the primary metric both strict (no forgiveness) and lenient, per arm, with counts of forgiven items. The findings block of every arm is parsed strictly by the production merge (src/superclaude/cli/review/findings.py), which is NOT edited: forgiveness lives only in the ledger parser. Files you may touch: scaffold/ledgerv1.py, analysis/analyze.py, new or existing tests under tests/, fixtures/reports/ (new report fixtures only), and DESIGN.md/TESTING.md additions. Files you must not touch: cards/, briefs/, sweep/extractors.py, words.py, formats.py, rank.py (frozen). Every file is under $SW; src/, tests/ (repo root), .claude/ and every existing .dev/tasks package are untouched; nothing is staged, committed or pushed; no model is started (tests use the fake claude); never open any ground-truth*.json. Python through uv.\" --depth standard --handoff none

Extra rules for the advisory plan review that the command runs at its end: its reviewers, calibrator and debaters must be claude-sonnet-5-5 or claude-haiku-5-5 class; if the protocol would use an Opus-class model, use Sonnet instead and say so in the contract."

run() { # label model prompt out
  ( cd "$REPO" && timeout 5400 bash "$LOCK" "$1" claude -p --model claude-sonnet-5-5 --output-format json --no-session-persistence --permission-mode bypassPermissions <<<"$2" ) >"$SW/option1-report/$3.json" 2>"$SW/option1-report/$3.err"
  echo "END $3 rc=$? $(date -u +%T)"
}
run ss-recall-repair "$PA" recall-repair &
run ss-forgive-plan "$PB" forgive-plan &
wait
echo ALLDONE
